import csv
from collections import Counter, defaultdict

rows = []
with open('/app/benchmark/data.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

def split_composers(composer_str):
    return [c.strip() for c in composer_str.split(',')]

# --- COMPUTE ALL STATISTICS ---

# Individual composer wins
individual_wins = Counter()
for row in rows:
    for c in split_composers(row['Composer']):
        individual_wins[c] += 1

# Unique composer credit lines (as-is)
credit_lines = [row['Composer'] for row in rows]
unique_credits = set(credit_lines)

# Unique individual composers
unique_individuals = set()
for row in rows:
    for c in split_composers(row['Composer']):
        unique_individuals.add(c)

total_unique = len(unique_individuals)

# Top composers (2+ wins)
top_composers = [(name, count) for name, count in individual_wins.most_common() if count >= 2]

# Max wins
max_wins_count = top_composers[0][1] if top_composers else 0
max_wins_names = [name for name, count in top_composers if count == max_wins_count]

# Repeat winner rate
# A ceremony is a "repeat win" if ANY individual composer in the winning credit had won before
seen_composers = set()
repeat_ceremony_count = 0
for row in rows:
    composers_in_entry = split_composers(row['Composer'])
    is_repeat = any(c in seen_composers for c in composers_in_entry)
    if is_repeat:
        repeat_ceremony_count += 1
    for c in composers_in_entry:
        seen_composers.add(c)

repeat_rate = (repeat_ceremony_count / len(rows)) * 100

# Decade analysis
def get_decade(year):
    return (year // 10) * 10

decade_data = defaultdict(lambda: {'years': [], 'composers': [], 'films': []})
for row in rows:
    yr = int(row['Year'])
    dec = get_decade(yr)
    decade_data[dec]['years'].append(yr)
    decade_data[dec]['films'].append(row['Film'])
    for c in split_composers(row['Composer']):
        decade_data[dec]['composers'].append(c)

decade_unique_counts = {}
for dec, data in sorted(decade_data.items()):
    decade_unique_counts[dec] = len(set(data['composers']))

most_unique_decade = max(decade_unique_counts, key=decade_unique_counts.get)
most_unique_decade_count = decade_unique_counts[most_unique_decade]

# Decade stats for charts
decade_labels = []
decade_ceremony_counts = []
decade_unique_composer_counts = []
decade_repeat_counts = []

for dec in sorted(decade_data.keys()):
    label = f"{dec}s"
    decade_labels.append(label)
    n_ceremonies = len(decade_data[dec]['years'])
    decade_ceremony_counts.append(n_ceremonies)
    unique_c = len(set(decade_data[dec]['composers']))
    decade_unique_composer_counts.append(unique_c)
    # Count repeat wins within this decade
    seen_before_decade = set()
    for row in rows:
        yr = int(row['Year'])
        if yr < dec:
            for c in split_composers(row['Composer']):
                seen_before_decade.add(c)
    repeats_in_decade = 0
    seen_during = set(seen_before_decade)
    for row in rows:
        yr = int(row['Year'])
        if get_decade(yr) == dec:
            composers_in_entry = split_composers(row['Composer'])
            is_repeat = any(c in seen_during for c in composers_in_entry)
            if is_repeat:
                repeats_in_decade += 1
            for c in composers_in_entry:
                seen_during.add(c)
    decade_repeat_counts.append(repeats_in_decade)

# Era analysis
era_boundaries = [
    ("Golden Age", 1934, 1959, "The symphonic tradition dominates: lush orchestral scores from European emigre composers define Hollywood's musical identity."),
    ("Silver Age", 1960, 1979, "The old guard gives way to bold experimentation — jazz, pop, and international influences break through the orchestral mold."),
    ("Modern Era", 1980, 1999, "Blockbuster scoring reaches its zenith. John Williams, John Barry, and Alan Menken define the sound of an industry transforming."),
    ("Contemporary Era", 2000, 2026, "Globalization and genre diversity reshape the award. Electronic textures, minimalism, and non-Western traditions earn recognition.")
]

era_stats = []
for era_name, start, end, description in era_boundaries:
    era_rows = [r for r in rows if start <= int(r['Year']) <= end]
    era_composers = []
    for r in era_rows:
        for c in split_composers(r['Composer']):
            era_composers.append(c)
    era_counter = Counter(era_composers)
    top_in_era = era_counter.most_common(5)
    era_stats.append({
        'name': era_name,
        'start': start,
        'end': end,
        'description': description,
        'n_ceremonies': len(era_rows),
        'unique_composers': len(set(era_composers)),
        'top_composers': top_in_era,
        'films': [(r['Year'], r['Film'], r['Composer']) for r in era_rows]
    })

# Notable milestones
# Longest gap between wins for a single composer
composer_years = defaultdict(list)
for row in rows:
    yr = int(row['Year'])
    for c in split_composers(row['Composer']):
        composer_years[c].append(yr)

longest_gap = 0
longest_gap_composer = ""
longest_gap_years = (0, 0)
for c, yrs in composer_years.items():
    if len(yrs) >= 2:
        sorted_yrs = sorted(yrs)
        for i in range(1, len(sorted_yrs)):
            gap = sorted_yrs[i] - sorted_yrs[i-1]
            if gap > longest_gap:
                longest_gap = gap
                longest_gap_composer = c
                longest_gap_years = (sorted_yrs[i-1], sorted_yrs[i])

# Back-to-back winners
back_to_back = []
for i in range(1, len(rows)):
    prev_composers = set(split_composers(rows[i-1]['Composer']))
    curr_composers = set(split_composers(rows[i]['Composer']))
    overlap = prev_composers & curr_composers
    if overlap:
        for c in overlap:
            back_to_back.append((c, int(rows[i-1]['Year']), int(rows[i]['Year']),
                                rows[i-1]['Film'], rows[i]['Film']))

# First-time winners per decade
first_time_per_decade = defaultdict(int)
all_seen = set()
for row in rows:
    yr = int(row['Year'])
    dec = get_decade(yr)
    composers_in_entry = split_composers(row['Composer'])
    for c in composers_in_entry:
        if c not in all_seen:
            first_time_per_decade[dec] += 1
            all_seen.add(c)

# Compile top composers data for chart (all with 2+ wins, sorted)
chart_composers = sorted(top_composers, key=lambda x: x[1])
chart_composer_names = [c[0] for c in chart_composers]
chart_composer_counts = [c[1] for c in chart_composers]

# Build complete winners table
winners_table_rows = ""
for row in rows:
    winners_table_rows += f"<tr><td>{row['Year']}</td><td>{row['Film']}</td><td>{row['Composer']}</td></tr>\n"

# --- DATA NOTES ---
# Note the Oppenheimer duplicate in 2023/2024
data_note = ""
oppenheimer_entries = [r for r in rows if r['Film'] == 'Oppenheimer']
if len(oppenheimer_entries) > 1:
    data_note = "Note: The dataset contains two entries for <em>Oppenheimer</em> (Ludwig Göransson) in both 2023 and 2024. This appears to be a data duplication. All statistics in this report are computed directly from the dataset as provided."

# --- GENERATE HTML ---

# Era sections HTML
era_sections_html = ""
era_colors = ["#D4AF37", "#e94560", "#4ecdc4", "#a78bfa"]
for i, era in enumerate(era_stats):
    top_list = ""
    for name, count in era['top_composers']:
        plural = "wins" if count > 1 else "win"
        top_list += f'<span class="era-composer-tag">{name} ({count} {plural})</span>'

    notable_films = ""
    step = max(1, len(era['films']) // 6)
    for j in range(0, min(len(era['films']), 6 * step), step):
        yr, film, comp = era['films'][j]
        notable_films += f'<div class="film-badge"><span class="film-year">{yr}</span> {film}</div>'

    era_sections_html += f'''
    <div class="era-block" style="border-left: 4px solid {era_colors[i]}">
        <div class="era-header">
            <h3 style="color: {era_colors[i]}">{era['name']} ({era['start']}–{era['end']})</h3>
            <div class="era-meta">
                <span class="era-stat">{era['n_ceremonies']} ceremonies</span>
                <span class="era-stat">{era['unique_composers']} unique composers</span>
            </div>
        </div>
        <p class="era-description">{era['description']}</p>
        <div class="era-top-composers">
            <strong>Defining voices:</strong><br>{top_list}
        </div>
        <div class="era-notable-films">
            <strong>Selected winners:</strong>
            <div class="film-badges">{notable_films}</div>
        </div>
    </div>'''

# Back-to-back HTML
b2b_html = ""
for c, y1, y2, f1, f2 in back_to_back:
    b2b_html += f'<li><strong>{c}</strong>: {f1} ({y1}) → {f2} ({y2})</li>'

# Milestones HTML
first_winner = rows[0]
last_winner = rows[-1]
single_win_composers = [name for name, count in individual_wins.items() if count == 1]

# Decade chart data
decade_first_time = [first_time_per_decade.get(dec, 0) for dec in sorted(decade_data.keys())]

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores</title>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<style>
:root {{
    --gold: #D4AF37;
    --gold-light: #f0d878;
    --gold-dark: #b8960c;
    --navy: #0d1117;
    --navy-light: #161b22;
    --navy-mid: #1c2333;
    --navy-card: #1a2030;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-muted: #6e7681;
    --accent-red: #e94560;
    --accent-teal: #4ecdc4;
    --accent-purple: #a78bfa;
    --accent-blue: #58a6ff;
    --border: #30363d;
}}

* {{ margin: 0; padding: 0; box-sizing: border-box; }}

body {{
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--navy);
    color: var(--text-primary);
    line-height: 1.7;
    overflow-x: hidden;
}}

.container {{
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 2rem;
}}

/* HERO */
.hero {{
    background: linear-gradient(135deg, var(--navy) 0%, #1a1a3e 50%, #2a1a2e 100%);
    padding: 5rem 0 4rem;
    text-align: center;
    position: relative;
    overflow: hidden;
}}

.hero::before {{
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle at 50% 50%, rgba(212,175,55,0.06) 0%, transparent 60%);
    animation: pulse 8s ease-in-out infinite;
}}

@keyframes pulse {{
    0%, 100% {{ transform: scale(1); opacity: 0.5; }}
    50% {{ transform: scale(1.1); opacity: 1; }}
}}

.hero h1 {{
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 3.2rem;
    font-weight: 800;
    color: var(--gold);
    margin-bottom: 0.75rem;
    position: relative;
    letter-spacing: -0.02em;
}}

.hero .subtitle {{
    font-size: 1.15rem;
    color: var(--text-secondary);
    max-width: 750px;
    margin: 0 auto 1rem;
    position: relative;
    font-weight: 300;
}}

.hero .meta {{
    font-size: 0.85rem;
    color: var(--text-muted);
    position: relative;
}}

/* KPI CARDS */
.kpi-section {{
    margin-top: -2.5rem;
    position: relative;
    z-index: 10;
    padding-bottom: 2rem;
}}

.kpi-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
}}

.kpi-card {{
    background: var(--navy-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 1.75rem 1.5rem;
    text-align: center;
    transition: transform 0.2s, border-color 0.2s;
}}

.kpi-card:hover {{
    transform: translateY(-2px);
    border-color: var(--gold);
}}

.kpi-value {{
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 2.8rem;
    font-weight: 800;
    color: var(--gold);
    line-height: 1.1;
    margin-bottom: 0.5rem;
}}

.kpi-label {{
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--text-secondary);
    margin-bottom: 0.25rem;
}}

.kpi-detail {{
    font-size: 0.78rem;
    color: var(--text-muted);
    font-style: italic;
}}

/* SECTIONS */
section {{
    padding: 3.5rem 0;
    border-top: 1px solid var(--border);
}}

section:first-of-type {{
    border-top: none;
}}

.section-header {{
    margin-bottom: 2rem;
}}

.section-header h2 {{
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 2rem;
    font-weight: 700;
    color: var(--gold-light);
    margin-bottom: 0.5rem;
}}

.section-header p {{
    color: var(--text-secondary);
    font-size: 0.95rem;
    max-width: 700px;
}}

.section-number {{
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--gold-dark);
    text-transform: uppercase;
    letter-spacing: 0.15em;
    margin-bottom: 0.3rem;
    display: block;
}}

/* CHARTS */
.chart-container {{
    background: var(--navy-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 2rem;
    margin: 1.5rem 0;
    position: relative;
}}

.chart-container canvas {{
    max-height: 450px;
}}

.chart-title {{
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 1rem;
}}

/* TABLES */
.data-table-wrapper {{
    overflow-x: auto;
    border-radius: 12px;
    border: 1px solid var(--border);
    margin: 1.5rem 0;
}}

table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
}}

thead th {{
    background: var(--navy-mid);
    color: var(--gold);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.75rem;
    padding: 1rem 1.25rem;
    text-align: left;
    position: sticky;
    top: 0;
}}

tbody td {{
    padding: 0.75rem 1.25rem;
    border-top: 1px solid var(--border);
    color: var(--text-primary);
}}

tbody tr:hover {{
    background: rgba(212, 175, 55, 0.04);
}}

tbody tr:nth-child(even) {{
    background: rgba(255,255,255,0.015);
}}

/* ERA BLOCKS */
.era-block {{
    background: var(--navy-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 2rem 2rem 2rem 2.5rem;
    margin: 1.5rem 0;
}}

.era-header {{
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    margin-bottom: 0.75rem;
}}

.era-header h3 {{
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.4rem;
    font-weight: 700;
}}

.era-meta {{
    display: flex;
    gap: 1rem;
}}

.era-stat {{
    font-size: 0.8rem;
    color: var(--text-muted);
    background: var(--navy-mid);
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
}}

.era-description {{
    color: var(--text-secondary);
    margin-bottom: 1rem;
    font-size: 0.95rem;
}}

.era-top-composers {{
    margin-bottom: 1rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}}

.era-composer-tag {{
    display: inline-block;
    background: rgba(212,175,55,0.1);
    color: var(--gold-light);
    padding: 0.2rem 0.7rem;
    border-radius: 15px;
    font-size: 0.82rem;
    margin: 0.25rem 0.25rem;
    border: 1px solid rgba(212,175,55,0.2);
}}

.era-notable-films {{
    color: var(--text-secondary);
    font-size: 0.9rem;
}}

.film-badges {{
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
}}

.film-badge {{
    font-size: 0.8rem;
    color: var(--text-secondary);
    background: var(--navy-mid);
    padding: 0.3rem 0.8rem;
    border-radius: 6px;
    border: 1px solid var(--border);
}}

.film-year {{
    color: var(--gold);
    font-weight: 600;
}}

/* MILESTONES */
.milestone-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
    gap: 1.25rem;
    margin: 1.5rem 0;
