import csv
from collections import defaultdict

rows = []
with open('/app/benchmark/data.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

def split_composers(s):
    return [c.strip() for c in s.split(',')]

decade_data = defaultdict(set)
for row in rows:
    yr = int(row['Year'])
    dec = (yr // 10) * 10
    for c in split_composers(row['Composer']):
